136	/// 手动解析查询串（percent-decode 后取 version / key）。
137	fn parse_snapshot_query(uri: &Uri) -> Result<SnapshotParams, String> {
138	    let mut version: Option<u64> = None;
139	    let mut key: Option<String> = None;
140	    if let Some(query) = uri.query() {
141	        for pair in query.split('&') {
142	            let Some((raw_name, raw_value)) = pair.split_once('=') else {
143	                return Err(format!("非法查询参数: {pair}"));
144	            };
145	            let name = percent_decode_str(raw_name).decode_utf8_lossy();
146	            let value = percent_decode_str(raw_value).decode_utf8_lossy();
147	            match name.as_ref() {
148	                "version" => {
149	                    version = Some(
150	                        value
151	                            .parse()
152	                            .map_err(|_| format!("version 必须是正整数: {value}"))?,
153	                    );
154	                }
155	                "key" => key = Some(value.into_owned()),
156	                other => return Err(format!("未知查询参数: {other}")),
157	            }
158	        }
159	    }
160	    match version {
161	        Some(version) => Ok(SnapshotParams { version, key }),
162	        None => Err("缺少必填查询参数 version".to_owned()),
163	    }
164	}
