211	/// POST /datasets/records：整体成功或整体失败的批量写入。
212	async fn write_records(
213	    State(state): State<AppState>,
214	    body: Bytes,
215	) -> Result<Json<WriteResponse>, (StatusCode, Json<ErrorBody>)> {
216	    // 解析与全部校验都在锁外完成；只有整批合法时才持锁一次性提交。
217	    let parsed: WriteRequest = serde_json::from_slice(&body)
218	        .map_err(|e| bad_request(format!("请求必须是包含 records 数组的 JSON 对象: {e}")))?;
219	
220	    if parsed.records.is_empty() {
221	        return Err(bad_request("records 不能为空批次"));
222	    }
223	
224	    let mut seen = HashSet::with_capacity(parsed.records.len());
225	    let mut batch: Vec<(String, Fields)> = Vec::with_capacity(parsed.records.len());
226	
227	    for (index, record) in parsed.records.into_iter().enumerate() {
228	        let fail = |message: &'static str| {
229	            (
230	                StatusCode::BAD_REQUEST,
231	                Json(ErrorBody {
232	                    error: message.to_owned(),
233	                    index: Some(index),
234	                }),
235	            )
236	        };
237	
238	        let mut object = match record {
239	            Value::Object(map) => map,
240	            _ => return Err(fail("每条记录必须是 JSON 对象")),
241	        };
242	
243	        let key = match object.remove("key") {
244	            Some(Value::String(key)) => key,
245	            Some(_) => return Err(fail("记录的 key 必须是字符串")),
246	            None => return Err(fail("记录缺少键 key")),
247	        };
248	
249	        let fields = match object.remove("fields") {
250	            Some(Value::Object(fields)) => fields,
251	            Some(_) => return Err(fail("记录的 fields 必须是 JSON 对象")),
252	            None => return Err(fail("记录缺少字段集 fields")),
253	        };
254	
255	        if !seen.insert(key.clone()) {
256	            return Err((
257	                StatusCode::CONFLICT,
258	                Json(ErrorBody {
259	                    error: format!("批次内出现重复键: {key}"),
260	                    index: Some(index),
261	                }),
262	            ));
263	        }
264	
265	        batch.push((key, fields));
266	    }
267	
268	    // 全部合法：持锁整体覆盖写入。任一条非法都在上面提前返回，数据集保持原状。
269	    let mut store = state.store.lock().unwrap();
270	    let written = batch.len();
271	    for (key, fields) in batch {
272	        store.dataset.insert(key, fields);
273	    }
274	    Ok(Json(WriteResponse {
275	        written,
276	        total: store.dataset.len(),
277	    }))
278	}
279	
280	/// POST /versions：把当前数据集固化为不可变快照。
281	async fn save_version(State(state): State<AppState>) -> Json<SaveResponse> {
282	    let mut store: MutexGuard<Store> = state.store.lock().unwrap();
283	    let version = store.snapshots.len() as u64 + 1;
284	    let records = store
285	        .dataset
286	        .iter()
287	        .map(|(key, fields)| (key.clone(), Value::Object(fields.clone())))
288	        .collect();
289	    let total = store.dataset.len();
290	    store.snapshots.push(Snapshot { version, records });
291	    Json(SaveResponse { version, total })
292	}
293	
294	/// GET /snapshots?version=N[&key=K]：读取历史快照。
295	async fn get_snapshot(
296	    State(state): State<AppState>,
297	    req: Request,
298	) -> Result<axum::response::Response, (StatusCode, Json<ErrorBody>)> {
299	    let params = parse_snapshot_query(req.uri()).map_err(bad_request)?;
300	
301	    let store = state.store.lock().unwrap();
302	    let snapshot = store
303	        .snapshots
304	        .iter()
305	        .find(|s| s.version == params.version)
306	        .cloned()
307	        .ok_or_else(|| {
308	            (
309	                StatusCode::NOT_FOUND,
310	                Json(ErrorBody {
311	                    error: format!("版本 {} 不存在或尚未保存", params.version),
312	                    index: None,
313	                }),
314	            )
315	        })?;
316	
317	    match params.key {
318	        Some(key) => {
319	            let fields = snapshot.records.get(&key).cloned().ok_or_else(|| {
320	                (
321	                    StatusCode::NOT_FOUND,
322	                    Json(ErrorBody {
323	                        error: format!("版本 {} 中不存在键 {key}", snapshot.version),
324	                        index: None,
325	                    }),
326	                )
327	            })?;
328	            Ok(Json(SnapshotRecord {
329	                version: snapshot.version,
330	                key,
331	                fields,
332	            })
333	            .into_response())
334	        }
335	        None => {
336	            // BTreeMap 的迭代顺序即键的字典序。
337	            let records = snapshot
338	                .records
339	                .into_iter()
340	                .map(|(key, fields)| RecordOut { key, fields })
341	                .collect();
342	            Ok(Json(SnapshotSummary {
343	                version: snapshot.version,
344	                records,
345	            })
346	            .into_response())
347	        }
348	    }
349	}
350	
351	/// GET /snapshots/diff?from=N&to=M：比较两份快照的记录级变化。
352	async fn diff_snapshots(
353	    State(state): State<AppState>,
354	    req: Request,
355	) -> Result<Json<DiffResponse>, (StatusCode, Json<ErrorBody>)> {
356	    let params = parse_diff_query(req.uri()).map_err(bad_request)?;
357	
358	    let store = state.store.lock().unwrap();
359	    let find = |version: u64| {
360	        store
361	            .snapshots
362	            .iter()
363	            .find(|s| s.version == version)
364	            .cloned()
365	            .ok_or_else(|| {
366	                (
367	                    StatusCode::NOT_FOUND,
368	                    Json(ErrorBody {
369	                        error: format!("版本 {version} 不存在或尚未保存"),
370	                        index: None,
371	                    }),
372	                )
373	            })
374	    };
375	    let from_snapshot = find(params.from)?;
376	    let to_snapshot = find(params.to)?;
377	
378	    // 两份快照的 records 都是 BTreeMap，按键归并即得字典序的键并集。
379	    let mut changes = Vec::new();
380	    let mut from_iter = from_snapshot.records.iter().peekable();
381	    let mut to_iter = to_snapshot.records.iter().peekable();
382	    loop {
383	        match (from_iter.peek(), to_iter.peek()) {
384	            (Some(&(from_key, from_fields)), Some(&(to_key, to_fields))) => {
385	                use std::cmp::Ordering::*;
386	                match from_key.cmp(to_key) {
387	                    Less => {
388	                        changes.push(ChangeOut {
389	                            key: from_key.clone(),
390	                            change: "removed",
391	                            fields: from_fields.clone(),
392	                        });
393	                        from_iter.next();
394	                    }
395	                    Greater => {
396	                        changes.push(ChangeOut {
397	                            key: to_key.clone(),
398	                            change: "added",
399	                            fields: to_fields.clone(),
400	                        });
401	                        to_iter.next();
402	                    }
403	                    Equal => {
404	                        // serde_json::Value 的相等即 JSON 值语义，与对象内字段顺序无关。
405	                        let (change, fields) = if from_fields == to_fields {
406	                            ("unchanged", Value::Null)
407	                        } else {
408	                            (
409	                                "modified",
410	                                serde_json::json!({
411	                                    "from": from_fields,
412	                                    "to": to_fields,
413	                                }),
414	                            )
415	                        };
416	                        changes.push(ChangeOut {
417	                            key: from_key.clone(),
418	                            change,
419	                            fields,
420	                        });
421	                        from_iter.next();
422	                        to_iter.next();
423	                    }
424	                }
425	            }
426	            (Some(&(from_key, from_fields)), None) => {
427	                changes.push(ChangeOut {
428	                    key: from_key.clone(),
429	                    change: "removed",
430	                    fields: from_fields.clone(),
431	                });
432	                from_iter.next();
433	            }
434	            (None, Some(&(to_key, to_fields))) => {
435	                changes.push(ChangeOut {
436	                    key: to_key.clone(),
437	                    change: "added",
438	                    fields: to_fields.clone(),
439	                });
440	                to_iter.next();
441	            }
442	            (None, None) => break,
443	        }
444	    }
445	
446	    Ok(Json(DiffResponse {
447	        from: from_snapshot.version,
448	        to: to_snapshot.version,
449	        changes,
450	    }))
451	}
452	
453	#[tokio::main]
454	async fn main() -> Result<(), Box<dyn Error>> {
455	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
456	    let listener = tokio::net::TcpListener::bind(&bind).await?;
457	    let state = AppState {
458	        store: std::sync::Arc::new(Mutex::new(Store::default())),
459	    };
460	    let app = Router::new()
461	        .route("/health", get(health))
462	        .route("/version", get(version))
463	        .route("/datasets/records", post(write_records))
464	        .route("/versions", post(save_version))
465	        .route("/snapshots", get(get_snapshot))
466	        .route("/snapshots/diff", get(diff_snapshots))
467	        .with_state(state);
468	
469	    println!("Listening on http://{}", listener.local_addr()?);
470	    axum::serve(listener, app)
471	        .with_graceful_shutdown(async {
472	            let _ = tokio::signal::ctrl_c().await;
473	        })
474	        .await?;
475	    Ok(())
476	}
