fn load(dir: &Path) -> io::Result<Recovered> {
    let mut committed: Vec<(u64, PathBuf)> = Vec::new();
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else { continue };
        // 清理上次崩溃可能留下的临时文件（未完成的提交对恢复不可见）
        if let Some(stem) = name.strip_suffix(".tmp") {
            if is_version_file_name(stem) {
                let _ = fs::remove_file(entry.path());
            }
            continue;
        }
        if let Some(version) = parse_version_file_name(name) {
            committed.push((version, entry.path()));
        }
    }
    committed.sort_by_key(|&(version, _)| version);

    let mut dataset = Dataset::new();
    let mut snapshots: Vec<Snapshot> = Vec::new();
    for (file_version, path) in committed {
        match load_entry(&path) {
            // 完整且校验通过：恢复该条目
            Ok(payload) if payload.version == file_version
                && snapshots.last().is_none_or(|s| payload.version > s.version) =>
            {
                dataset = payload.dataset;
                snapshots.push(Snapshot { version: payload.version, records: payload.snapshot });
            }
            // 半写或校验失败：按不存在处理并跳过，后续完整条目照常恢复
