```rust
// ---------- 持久化 ----------

/// CRC32 (IEEE) 校验和，用于识别半写或损坏的落盘条目。
const CRC_TABLE: [u32; 256] = build_crc_table();

const fn build_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0;
    while i < 256 {
        let mut c = i as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xEDB8_8320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        table[i] = c;
        i += 1;
    }
    table
}

fn crc32(bytes: &[u8]) -> u32 {
    let mut c = 0xFFFF_FFFFu32;
    for &b in bytes {
        c = CRC_TABLE[((c ^ u32::from(b)) & 0xFF) as usize] ^ (c >> 8);
    }
    c ^ 0xFFFF_FFFF
}

/// 每个已提交版本对应目录下一个 `v<N>.json` 文件；写入过程使用 `v<N>.json.tmp`。
fn version_file_name(version: u64) -> String {
    format!("v{version}.json")
}

fn parse_version_file_name(name: &str) -> Option<u64> {
    name.strip_prefix('v')?
        .strip_suffix(".json")?
        .parse()
        .ok()
}

fn invalid_data(message: impl Into<String>) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message.into())
}

/// 从落盘文件反序列化出的单条条目。
#[derive(Deserialize)]
struct StoredPayload {
    version: u64,
    dataset: Dataset,
    snapshot: BTreeMap<String, Fields>,
}

/// 原子提交一个版本：版本记录、快照与当时的数据集一起写入 `v<N>.json`。
///
/// 先写临时文件并 fsync，再 rename 成正式文件并 fsync 目录。rename 之前崩溃或
/// 失败，磁盘上只可能残留临时文件，正式条目不会出现；调用方据此保证版本号可复用。
fn commit_version(
    dir: &Path,
    version: u64,
    dataset: &Dataset,
    snapshot: &BTreeMap<String, Value>,
) -> io::Result<()> {
    let payload_json = serde_json::to_string(&serde_json::json!({
        "version": version,
        "dataset": dataset,
        "snapshot": snapshot,
    }))
    .map_err(|e| invalid_data(format!("序列化版本 {version} 失败: {e}")))?;
    let content = format!(
        "{{\"payload\":{payload_json},\"checksum\":\"{:08x}\"}}",
        crc32(payload_json.as_bytes())
    );

    let final_path = dir.join(version_file_name(version));
    let tmp_path = final_path.with_extension("json.tmp");
    let result = (|| -> io::Result<()> {
        let mut file = fs::File::create(&tmp_path)?;
        file.write_all(content.as_bytes())?;
        file.sync_all()?;
        drop(file);
        fs::rename(&tmp_path, &final_path)?;
        // fsync 目录本身，确保 rename 的结果崩溃后仍可见。
        fs::File::open(dir)?.sync_all()?;
        Ok(())
    })();
    if result.is_err() {
        // 失败不留痕迹：清掉可能已写了一半的临时文件。
        let _ = fs::remove_file(&tmp_path);
    }
    result
}
